[JsonPropertyName("isCurrentlyConnected")]
public bool IsCurrentlyConnected
{
    get => _isCurrentlyConnected;
    set
    {
        if (_isCurrentlyConnected != value)
        {
            _isCurrentlyConnected = value;
            OnPropertyChanged();
            OnPropertyChanged(nameof(IsDisconnectedRetained));
        }
    }
}

public bool IsDisconnectedRetained => !IsCurrentlyConnected;

public MonitorInfo()
