monitors = MonitorSettingsRebuilder.Rebuild(
    currentlyDiscovered: monitors,
    existing: retentionInput,
    clock: _clock,
    retentionDays: PowerDisplaySettings.MonitorEntryRetentionDays);

var visible = allFromDisk.Where(m => IsVisibleMonitorId(m.Id)).ToList();
var active = visible.Where(m => m.IsCurrentlyConnected).ToList();
var disconnected = visible.Where(m => !m.IsCurrentlyConnected).ToList();

Monitors = new ObservableCollection<MonitorInfo>(active);
DisconnectedMonitors = new ObservableCollection<MonitorInfo>(disconnected);

public void ForgetDisconnectedMonitor(MonitorInfo monitor)
{
    _settings.Properties.Monitors.RemoveAll(m => MonitorIdComparer.Equal(m.Id, monitor.Id));
    DisconnectedMonitors.Remove(monitor);
    SettingsUtils.SaveSettings(_settings.ToJsonString(), PowerDisplaySettings.ModuleName);
}
